346	  // --describe subprocess per Verilator build only to fail on the argument.
347	  if (int rc = check_one_elf(cli, "cycle")) return rc;
348	  // --mem-size is validated but has nothing to size: the cycle engine always
349	  // models its full DRAM window. Say so instead of silently ignoring it.
350	  if (!cli.mem_size.empty()) {
351	    std::string se;
352	    if (parse_size(cli.mem_size, se); !se.empty()) {
353	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
354	                   se.c_str());
