356	    }
357	    log_line(kLogWarn,
358	             "[andesim] --mem-size: the cycle engine models its full "
359	             "DRAM window; nothing to size");
360	  }
361	  Discovery disc = discover_engines();
362	  std::string err;
363	  const EngineDescriptor* eng =
364	      resolve_accurate_engine(disc.engines, cli.engine, err);
365	  if (!eng) {
366	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
367	    // Surface why an expected engine may be absent (failed --describe, etc.).
368	    for (const std::string& w : disc.warnings)
369	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
370	    return 2;
371	  }
372	  // The ELF must match the engine's width: an rv32 ELF on an rv64 engine (or
373	  // vice versa) cannot run. Catch it here with a clear message instead of the
374	  // engine's cryptic "not of ELFCLASSxx". check_one_elf above guaranteed a lone
375	  // positional.
376	  if (std::string e = elf_engine_arch_error(cli.positional[0], *eng); !e.empty()) {
377	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", e.c_str());
378	    return 2;
379	  }
