381	  // precedence over the interactive --gdb path (a dry run launches no debugger).
382	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
383	  // clean_output: hide vsim's banner + [info] log, restate the cycle count under
384	  // [andesim] (fast keeps raw passthrough -- QEMU has no such banner and its
385	  // monitor/gdbstub are interactive).
386	  return run_standalone(cli, *eng, "cycle", /*extra=*/{}, /*clean_output=*/true);
