391	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
392	// driver's tests/e2e.sh delegation with a single window-cycle line.
393	int run_hybrid(const Cli& cli) {
394	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
395	  auto fail = [](const std::string& msg) {
396	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
397	    return 2;
398	  };
399	
400	  // --print-memmap: the map describes the run's window (engine + --mem-size),
401	  // not a workload, so the ELF is optional (when given it only adds the
402	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
403	  const bool memmap_only = cli.print_memmap;
