410	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
411	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
412	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
413	  std::string elf_path;
414	  if (!cli.positional.empty()) {
415	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
416	    if (elf_path.empty()) return 2;
417	  }
418	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
419	
420	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
421	  // mistake fails fast without spawning a --describe per Verilator build.
422	  std::string err;
423	  Trigger trig;
424	  std::vector<std::string> vsim_extras;
425	  if (!memmap_only) {
426	    trig = hybrid_trigger(cli, elf_path, err);
427	    if (!err.empty()) return fail(err);
428	
429	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
430	    // hybrid triggers; unknown returned an error above) -- exactly the entry
431	    // boundary --verify needs the oracle to arm on.
432	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
433	    if (!err.empty()) return fail(err);
434	  }
435	
436	  // --runtime linux (U9) defaults --mem-size to 1G, same as fast (U2) --
437	  // the app + vlinux's own arenas need more than the plain hybrid default.
438	  long long mem = cli.runtime == "linux" ? 1024LL * 1024 * 1024
439	                                         : 128LL * 1024 * 1024;
440	  if (!cli.mem_size.empty()) {
441	    std::string se;
442	    mem = parse_size(cli.mem_size, se);
443	    if (!se.empty()) return fail("--mem-size: " + se);
444	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
445	    // guest RAM here. The physical mmap reserves one V-scratch page above the
446	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
447	    // page. Failing now beats allocating a huge mmap file first and letting
448	    // QEMU die late.
449	    if (mem > max_program_mem_bytes())
450	      return fail("--mem-size " + cli.mem_size +
451	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
452	                  "reservation)");
453	  }
454	
455	  // L26/F3: refuse a run whose static image would extend into the reserved
456	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
457	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
458	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
459	  // scratch -> silent corruption. Derive the page's start from
460	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
461	  // `mem`, so the threshold tracks the reservation shape instead of relying on
462	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
463	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
464	  // reports it.
465	  {
466	    std::string e;
467	    const uint64_t top = elf_load_top(elf_path, e);
468	    const uint64_t scratch_gpa =
469	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
470	    if (e.empty() && top > scratch_gpa) {
471	      char msg[256];
472	      std::snprintf(msg, sizeof(msg),
473	                    "ELF static image ends at 0x%llx, overlapping the reserved "
474	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
475	                    "; raise --mem-size or shrink the image",
476	                    static_cast<unsigned long long>(top),
477	                    static_cast<unsigned long long>(scratch_gpa));
