1	// `andesim profile [--engine <id>] [report flags] ELF [-- <qemu args>]`.
2	//
3	// Hot inner-loop detection on the FUNCTIONAL engine, configured like the
4	// hybrid fast leg: profile picks a cycle-accurate engine (--engine or the
5	// sole one, the same selector cycle/hybrid use) and derives the QEMU launch
6	// from it -- the CPU model from the engine's `--print-qemu-config` driver
7	// globals, vlen from its --describe, and the staged qemu.cfg as -readconfig.
8	// That keeps the profiled ISA identical to the engine the reported
9	// `measure: --pc-start/--pc-end` windows will be measured on (a wrong vlen
10	// changes vsetvl trip counts, i.e. the hot-loop ranking itself).
11	//
12	// QEMU runs the ELF to completion with the hotIterationLoop TCG plugin; the
13	// plugin's
14	// `-d plugin -D` log is parsed, filtered (min-iters, RVV-only), nested, and
15	// rendered as the LLM Markdown report (or --no-llm table). All pure logic
16	// lives in profile.cpp; this file owns the IO: engine resolve, the cfg probe,
17	// the QEMU spawn, objdump/addr2line, and the per-loop symbol lookups.
18	#include <sys/wait.h>
19	#include <unistd.h>
20	
21	#include <algorithm>
22	#include <cstdint>
23	#include <cstdio>
24	#include <cstdlib>
25	#include <filesystem>
26	#include <fstream>
27	#include <map>
28	#include <sstream>
29	#include <string>
30	#include <vector>
31	
32	#include "argv.hpp"
33	#include "cli.hpp"
34	#include "config_env.hpp"
35	#include "elf_syms.hpp"
36	#include "engine_descriptor.hpp"
37	#include "engine_registry.hpp"
38	#include "log.hpp"
39	#include "process.hpp"
40	#include "strutil.hpp"
41	#include "profile.hpp"
42	#include "repo_root.hpp"
43	#include "run_plan.hpp"
44	
45	namespace fs = std::filesystem;
46	
47	namespace andes_sim {
48	namespace {
49	
50	// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
51	bool cmd_exists(const std::string& cmd) {
52	  if (cmd.find('/') != std::string::npos)
53	    return ::access(cmd.c_str(), X_OK) == 0;
54	  const char* path_env = std::getenv("PATH");
55	  if (!path_env) return false;
56	  std::istringstream ss(path_env);
57	  std::string dir;
58	  while (std::getline(ss, dir, ':'))
59	    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
60	      return true;
61	  return false;
62	}
63	
64	std::string find_first(const std::vector<std::string>& cands) {
65	  for (const auto& c : cands)
66	    if (cmd_exists(c)) return c;
67	  return "";
68	}
69	
70	// The cross objdump chain: --objdump wins, else $HYBRID_TOOLCHAIN (env or
71	// config.env) so RISC-V vendor extensions (RVV, Andes custom) decode
72	// correctly -- generic llvm-objdump on old distros may not know RVV.
73	std::string resolve_objdump(const std::string& override_path) {
74	  if (!override_path.empty()) return override_path;
75	  std::vector<std::string> cands;
76	  if (const std::string tc = config_env_value("HYBRID_TOOLCHAIN"); !tc.empty()) {
77	    cands.push_back(tc + "/bin/riscv64-unknown-elf-objdump");
78	    cands.push_back(tc + "/bin/riscv32-unknown-elf-objdump");
79	  }
80	  cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
81	                             "riscv32-unknown-elf-objdump", "llvm-objdump",
82	                             "objdump"});
83	  return find_first(cands);
84	}
85	
86	// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
87	// takes one hex address per input line.
88	std::string capture_with_stdin(const std::vector<std::string>& argv,
89	                               const std::string& input) {
90	  if (argv.empty()) return "";
91	  int in_fds[2], out_fds[2];
92	  if (pipe(in_fds) != 0) return "";
93	  if (pipe(out_fds) != 0) {
94	    close(in_fds[0]);
95	    close(in_fds[1]);
96	    return "";
97	  }
98	  pid_t pid = fork();
99	  if (pid < 0) {
100	    close(in_fds[0]); close(in_fds[1]);
101	    close(out_fds[0]); close(out_fds[1]);
102	    return "";
103	  }
104	  if (pid == 0) {
105	    close(in_fds[1]);
106	    close(out_fds[0]);
107	    dup2(in_fds[0], STDIN_FILENO);
108	    dup2(out_fds[1], STDOUT_FILENO);
109	    if (FILE* devnull = std::fopen("/dev/null", "w"))
110	      dup2(fileno(devnull), STDERR_FILENO);
111	    close(in_fds[0]);
112	    close(out_fds[1]);
113	    std::vector<char*> cargv;
114	    cargv.reserve(argv.size() + 1);
115	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
116	    cargv.push_back(nullptr);
117	    execvp(cargv[0], cargv.data());
118	    _exit(127);
119	  }
120	  close(in_fds[0]);
121	  close(out_fds[1]);
122	  const char* p = input.data();
123	  size_t rem = input.size();
124	  while (rem > 0) {
125	    ssize_t w = write(in_fds[1], p, rem);
126	    if (w < 0) break;
127	    p += w;
128	    rem -= static_cast<size_t>(w);
129	  }
130	  close(in_fds[1]);
131	  std::string out;
132	  char buf[4096];
133	  ssize_t n;
134	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
135	    out.append(buf, static_cast<size_t>(n));
136	  close(out_fds[0]);
137	  int status = 0;
138	  waitpid(pid, &status, 0);
139	  return out;
140	}
141	
142	// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
143	// out, so absent keys mean "no source info".
144	std::map<uint64_t, std::string> resolve_sources(
145	    const std::string& addr2line_bin, const std::string& elf_path,
146	    const std::vector<uint64_t>& pcs) {
147	  std::map<uint64_t, std::string> result;
148	  if (addr2line_bin.empty() || pcs.empty()) return result;
149	  std::string input;
150	  for (uint64_t pc : pcs) {
151	    char buf[20];
152	    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
153	    input += buf;
154	  }
155	  const std::string out =
156	      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
157	  std::istringstream ss(out);
158	  std::string line;
159	  size_t idx = 0;
160	  while (std::getline(ss, line) && idx < pcs.size()) {
161	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
162	      line.pop_back();
163	    if (!line.empty() && line.find("??") == std::string::npos)
164	      result[pcs[idx]] = line;
165	    ++idx;
166	  }
167	  return result;
168	}
169	
170	// The trimmed text of `path`'s line `lineno` ("" when unreadable).
171	std::string read_source_line(const std::string& path, int lineno) {
172	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
173	  std::ifstream f(path);
174	  std::string line;
175	  for (int i = 1; std::getline(f, line); ++i) {
176	    if (i != lineno) continue;
177	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
178	                             line.back() == ' ' || line.back() == '\t'))
179	      line.pop_back();
180	    auto s = line.find_first_not_of(" \t");
181	    return (s != std::string::npos) ? line.substr(s) : line;
182	  }
183	  return "";
184	}
185	
186	// "name+0xoff" (or "") when the ELF resolves `pc`, else the raw hex pc.
187	std::string sym_or_hex(const std::string& sym, uint64_t pc) {
188	  if (!sym.empty()) return sym;
189	  char buf[20];
190	  std::snprintf(buf, sizeof(buf), "0x%llx", (unsigned long long)pc);
191	  return buf;
192	}
193	
194	// Fill one loop's LoopSyms from the ELF + the resolved source map. One
195	// symbolize() per endpoint (each call re-reads the ELF's symtab): the bare
196	// function name is the start symbol with its "+0xoff" stripped.
197	LoopSyms make_syms(const std::string& elf, uint64_t start, uint64_t end,
198	                   const std::map<uint64_t, std::string>& src_map) {
199	  LoopSyms s;
200	  const std::string raw_start = symbolize(elf, start);
201	  s.sym_start = sym_or_hex(raw_start, start);
202	  s.sym_end = sym_or_hex(symbolize(elf, end), end);
203	  s.fn_name = raw_start.substr(0, raw_start.find('+'));
204	  auto [fe, fx] = fn_range(elf, start);
205	  s.fn_entry = fe;
206	  s.fn_end = fx;
207	  if (auto it = src_map.find(start); it != src_map.end()) s.src_start = it->second;
208	  if (auto it = src_map.find(end); it != src_map.end()) s.src_end = it->second;
209	  auto [path, lineno] = parse_file_line(s.src_start);
210	  s.code_snippet = read_source_line(path, lineno);
211	  return s;
212	}
