425	  // One syms vector serves both renderers: build_loops keeps row order, so
426	  // `loops` is parallel to `rows`.
427	  std::vector<LoopSyms> syms;
428	  syms.reserve(rows.size());
429	  for (const auto& r : rows)
430	    syms.push_back(make_syms(elf, r.start, r.end, src_map));
431	
432	  const std::string report =
433	      cli.llm ? render_llm(build_loops(rows, limit), syms, total_iters,
434	                           abs.filename().string(), disasm, min_iters,
435	                           cli.optimize_rvv)
436	              : render_table(rows, syms, min_iters, cli.optimize_rvv);
437	  std::fputs(report.c_str(), stdout);
438	  return 0;
439	}
