47	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
48	// success; on failure prints an error tagged with `ctx` and returns "". The
49	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
50	// missing path fails with a clear "ELF not found" instead of being handed to the
51	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
52	// up-front check run_hybrid already does.
53	std::string abs_elf(const std::string& path, const std::string& ctx) {
54	  std::error_code ec;
55	  fs::path abs = fs::absolute(path, ec);
56	  if (ec) {
57	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
58	                 ctx.c_str(), path.c_str());
59	    return "";
60	  }
61	  if (!fs::is_regular_file(abs, ec)) {
62	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
63	                 path.c_str());
64	    return "";
65	  }
66	  return abs.string();
67	}
