91	// elf_engine_arch_error (the ELF-vs-engine width guard shared with profile)
92	// lives in engine_registry.hpp, next to resolve_accurate_engine.
93	
94	// print_dry_run (the shared --dry-run preview) lives in argv.hpp, next to
95	// render_argv.
