97	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
98	// and verbose [info] log (VsimFilter), relaying only the program's own output
99	// and any real diagnostics, then restate the lifted cycle count as andesim's own
100	// one-line result under the [andesim] prefix. The count is printed AFTER the run
101	// (the engine logs it at exit), so it follows the program output. Returns the
102	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
103	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
104	int run_cycle_clean(const std::vector<std::string>& argv) {
105	  VsimFilter filter;
106	  const int rc = run_line_filtered(
107	      argv, [&filter](int stream, std::string_view line) {
108	        std::FILE* dst = nullptr;
109	        switch (filter.classify(stream, line)) {
110	          case VsimFilter::Dest::kStdout: dst = stdout; break;
111	          case VsimFilter::Dest::kStderr: dst = stderr; break;
112	          case VsimFilter::Dest::kDrop: return;
113	        }
114	        std::fwrite(line.data(), 1, line.size(), dst);
115	        std::fputc('\n', dst);
116	      });
117	  if (const std::optional<uint64_t> c = filter.cycles())
118	    log_result(kLogInfo, "[andesim] %llu cycles",
119	               static_cast<unsigned long long>(*c));
120	  return rc;
121	}
