123	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
124	// then run the resolved engine standalone with `extra` (model flags the
125	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
126	// `clean_output` picks how the engine's output is presented: fast inherits the
127	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
128	// semihosting console works unchanged); cycle filters out the engine's banner +
129	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
130	// exit code propagates. The per-model engine + selection are resolved by the
131	// caller; `model` here only labels the positional diagnostics.
132	// `boot_elf_override`: --runtime linux (U2) boots a staged vlinux.elf instead
133	// of the positional ELF (which stays the APP path -- still validated to
134	// exist, still what the manifest embeds); empty means "boot the ELF as given"
135	// (every other caller).
136	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
137	                   const char* model, const std::vector<std::string>& extra = {},
138	                   bool clean_output = false,
139	                   const std::string& boot_elf_override = {}) {
140	  if (int rc = check_one_elf(cli, model)) return rc;
141	  // QEMU's -bios flag searches its data directory for relative paths rather
142	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
143	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
144	  if (elf.empty()) return 2;
145	  const std::string& boot_elf =
146	      boot_elf_override.empty() ? elf : boot_elf_override;
147	  std::vector<std::string> args = extra;
148	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
149	  std::string err;
150	  const std::vector<std::string> argv =
151	      passthrough_argv(eng, "standalone", boot_elf, args, err);
152	  if (!err.empty()) {
153	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
154	    return 2;
155	  }
156	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
157	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
158	  if (cli.dry_run)
159	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
160	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
161	  // wedged engine still leaves the exact command in the log.
162	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
163	           render_argv(argv).c_str());
164	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
165	}
