167	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
168	// only the built-in qemu descriptor, so it resolves that directly rather than
169	// discover_engines(), which would spawn a --describe subprocess per Verilator
170	// build only to discard them all here.
171	int run_fast(const Cli& cli) {
172	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
173	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
174	    std::fprintf(stderr,
175	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
176	                 "got '%s'\n",
177	                 cli.engine.c_str());
178	    return 2;
179	  }
180	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
181	  // (the app + vlinux's own arenas) when the user did not pick one.
182	  std::string mem_size_spec = cli.mem_size;
183	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
184	
185	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
186	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
187	  std::string err;
188	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
189	  if (!err.empty()) {
190	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
191	    return 2;
192	  }
193	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
194	  if (cli.gdb) {
195	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
196	    extra.push_back("-gdb");
197	    extra.push_back("tcp::" + port);
198	    extra.push_back("-S");
199	  }
200	
201	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
202	  // the proxy kernel. The ELF positional is the APP, not the boot image --
203	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
204	  Cli cli2 = cli;
205	  std::string boot_elf;
206	  if (cli.runtime == "linux") {
207	    if (int rc = check_one_elf(cli, "fast")) return rc;
208	    const std::string app_elf =
209	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
210	    if (app_elf.empty()) return 2;
211	
212	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
213	    // strictly tighter validation than parse_size alone), so this call
214	    // cannot fail: reused only to get the byte count for the manifest.
215	    const long long mem_bytes = parse_size(mem_size_spec, err);
216	
217	    std::string stage_err;
218	    boot_elf = stage_linux_runtime(app_elf, static_cast<uint64_t>(mem_bytes),
219	                                   cli.passthrough, stage_err);
220	    if (boot_elf.empty()) {
221	      std::fprintf(stderr, "andesim run --mode fast --runtime linux: %s\n",
222	                   stage_err.c_str());
223	      return 2;
224	    }
225	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
226	             boot_elf.c_str(), app_elf.c_str());
227	
228	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
229	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
230	    // engine flags (e.g. "-m x.gguf" is not a memory size).
231	    cli2.passthrough.clear();
232	
233	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
234	    // measurement targets, not the ax46 vplat default (last -cpu wins).
235	    extra.push_back("-cpu");
236	    extra.push_back("andes-ax45mpv,vlen=512");
237	  }
238	
239	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
240	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
241	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
242	  // ELF -- the override is the user's call.
243	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
244	  int xlen;
245	  if (cli.engine == kQemuId32) xlen = 32;
246	  else if (cli.engine == kQemuId64) xlen = 64;
247	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
248	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
249	  // == elf_w), so this guard already implies an explicit --engine.
250	  if (elf_w && elf_w != xlen)
251	    std::fprintf(stderr,
252	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
253	                 "(running as rv%d)\n",
254	                 cli.engine.c_str(), xlen, elf_w, xlen);
255	  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
256	                        /*clean_output=*/false, boot_elf);
257	}
