259	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
260	// its --jtag-port only after it has reset and halted the hart, so the debugger we
261	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
262	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
263	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
264	// single debugger slot). Returns false on timeout.
265	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
266	  constexpr int kPollMs = 50;
267	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
268	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
269	      char line[512];
270	      while (std::fgets(line, sizeof line, f)) {
271	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
272	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
273	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
274	        unsigned lport = 0, st = 0;
275	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
276	            && st == 0x0A && lport == port) {
277	          std::fclose(f);
278	          return true;
279	        }
280	      }
281	      std::fclose(f);
282	    }
283	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
284	  }
285	  return false;
286	}
