288	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
289	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
290	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
291	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
292	  const char* iceman = std::getenv("ICEMAN");
293	  if (!iceman || !*iceman) {
294	    std::fprintf(stderr,
295	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
296	                 "(export ICEMAN=<path to ICEman binary>)\n");
297	    return 2;
298	  }
299	  // Build vsim argv from the standalone template, appending user passthrough
300	  // and the JTAG port flag.
301	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
302	  if (elf.empty()) return 2;
303	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
304	  std::vector<std::string> vsim_pass = cli.passthrough;
305	  vsim_pass.push_back("--jtag-port");
306	  vsim_pass.push_back(jtag_port);
307	  std::string err;
308	  const std::vector<std::string> vsim_argv =
309	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
310	  if (!err.empty()) {
311	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
312	    return 2;
313	  }
314	  std::fprintf(stderr,
315	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
316	               jtag_port.c_str());
317	  if (fork_background(vsim_argv) < 0) {
318	    std::fprintf(stderr,
319	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
320	    return 1;
321	  }
322	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
323	  // Wait for the port to be LISTENing before launching the debugger (it does not
324	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
325	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
326	  // but launch anyway if it never appears.
327	  if (const int pnum = std::atoi(jtag_port.c_str());
328	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
329	    std::fprintf(stderr,
330	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
331	                 "after 20s; launching the debugger anyway\n",
332	                 jtag_port.c_str());
333	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
334	  // localhost, port 9104) instead of its default real-hardware adapter; without
335	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
336	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
337	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
338	}
