// resolve_accurate_engine plus its shared failure reporting: on failure print
// "<ctx>: <err>" and one "andesim: skipped engine: ..." line per discovery
// warning (why an expected engine may be absent -- failed --describe, etc.) to
// stderr, then return nullptr (the caller's exit-2 path). Takes the CALLER's
// Discovery -- the returned pointer aliases disc.engines, which callers keep
// using after resolution -- so `disc` must outlive the result. One wording,
// shared by `run --mode cycle`, `run --mode hybrid`, and `profile`.
inline const EngineDescriptor* resolve_accurate_engine_or_report(
    const Discovery& disc, const std::string& want_id, const char* ctx) {
  std::string err;
  const EngineDescriptor* eng =
      resolve_accurate_engine(disc.engines, want_id, err);
  if (!eng) {
    std::fprintf(stderr, "%s: %s\n", ctx, err.c_str());
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
  }
  return eng;
}

