1	// `andesim doctor` -- read-only environment health.
2	//
3	// Four sections (artifacts, submodules, toolchain, runtime) plus a Summary
4	// line. The detail strings point at scripts/build_all.sh -- the build entry
5	// point, since the build command lives in that script, not the binary.
6	// After Summary the driver appends an `engines:` readout sourced from F2
7	// discovery -- INFO-tagged, never affecting the exit code (which stays 1 iff
8	// any FAIL row).
9	#include <algorithm>
10	#include <cctype>
11	#include <cstdio>
12	#include <cstdlib>
13	#include <filesystem>
14	#include <fstream>
15	#include <string>
16	#include <vector>
17	
18	#include <sys/statvfs.h>
19	#include <unistd.h>
20	
21	#include "cli.hpp"
22	#include "engine_registry.hpp"
23	#include "repo_root.hpp"
24	#include "shm.hpp"
25	#include "strutil.hpp"
26	
27	namespace fs = std::filesystem;
28	
29	namespace andes_sim {
30	namespace {
31	
32	// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
33	// feed the summary, and only FAIL gates the exit code.
34	struct Row {
35	  std::string name;
36	  std::string status;
37	  std::string detail;
38	};
39	
40	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
41	std::string strip_char(std::string s, char c) {
42	  size_t b = 0, e = s.size();
43	  while (b < e && s[b] == c) ++b;
44	  while (e > b && s[e - 1] == c) --e;
45	  return s.substr(b, e - b);
46	}
47	
48	// --- artifacts --------------------------------------------------------------
49	
50	std::vector<Row> doctor_artifacts() {
51	  const fs::path root = repo_root();
52	  struct A {
53	    const char* label;
54	    const char* env;
55	    fs::path def;
56	  };
57	  // The vsim/qemu defaults come straight from the registry's resolvers
58	  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
59	  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
60	  // tiers.
61	  const A arts[] = {
62	      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
63	      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
64	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
65	  };
66	  std::vector<Row> rows;
67	  for (const A& a : arts) {
68	    const char* ov = std::getenv(a.env);
69	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
70	    if (fs::is_regular_file(p))
71	      rows.push_back({a.label, "PASS", p.string()});
72	    else
73	      rows.push_back(
74	          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
75	  }
76	
77	  const fs::path fix = root / "tests" / "fixtures";
78	  size_t elfs = 0;
79	  std::error_code ec;
80	  if (fs::is_directory(fix, ec))
81	    for (const auto& e : fs::directory_iterator(fix, ec))
82	      if (e.path().extension() == ".elf") ++elfs;
83	  if (elfs > 0)
84	    rows.push_back(
85	        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
86	  else
87	    rows.push_back({"fixtures", "FAIL",
88	                    "no *.elf in " + fix.string() +
89	                        " -- run make -C tests/fixtures"});
90	  return rows;
91	}
92	
93	// --- submodules -------------------------------------------------------------
94	
95	std::vector<Row> doctor_submodules() {
96	  const fs::path root = repo_root();
97	  struct M {
98	    const char* name;
99	    fs::path marker;
100	    const char* rel;  // marker, repo-relative (the PASS detail)
101	  };
102	  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
103	  // external binaries, checked in the artifacts section (qemu/vsim rows) via
104	  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
105	  const M ms[] = {
106	      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
107	       "include/hybrid/state_abi.h"},
108	  };
109	  std::vector<Row> rows;
110	  for (const M& m : ms) {
111	    if (fs::is_regular_file(m.marker))
112	      rows.push_back({m.name, "PASS", m.rel});
113	    else
114	      rows.push_back({m.name, "FAIL",
115	                      "missing " + m.marker.string() +
116	                          " -- run 'git submodule update --init --recursive'"});
117	  }
118	  return rows;
119	}
120	
121	// --- toolchain --------------------------------------------------------------
122	
123	// First PATH directory holding an executable non-directory named `tool`, joined
124	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
125	std::string which(const std::string& tool) {
126	  const char* path = std::getenv("PATH");
127	  if (!path) return "";
128	  const std::string p(path);
129	  for (size_t i = 0; i <= p.size();) {
130	    size_t j = p.find(':', i);
131	    if (j == std::string::npos) j = p.size();
132	    std::string dir = p.substr(i, j - i);
133	    i = j + 1;
134	    if (dir.empty()) continue;
135	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
136	    std::error_code ec;
137	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
138	      return cand;
139	  }
140	  return "";
141	}
142	
143	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
144	// to the value with surrounding whitespace, then double, then single quotes
145	// stripped (mirrors hsim._read_hybrid_toolchain).
146	bool parse_toolchain_line(const std::string& line, std::string& out) {
147	  size_t i = 0, n = line.size();
148	  auto skip_ws = [&] {
149	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
150	  };
151	  skip_ws();
152	  const std::string kw = "export";
153	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
154	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
155	    i += kw.size();
156	    skip_ws();
157	  }
158	  const std::string key = "HYBRID_TOOLCHAIN";
159	  if (line.compare(i, key.size(), key) != 0) return false;
160	  i += key.size();

