  const fs::path root = repo_root();
  struct A {
    const char* label;
    const char* env;
    fs::path def;
  };
  // The vsim/qemu defaults come straight from the registry's resolvers
  // (vsim_scan_dir / builtin_qemu_arch), so doctor reports the same paths the
  // engine would use instead of re-deriving the env -> QEMU_BIN_DIR -> legacy
  // tiers.
  const A arts[] = {
      {"vsim", "VSIM_BIN", vsim_scan_dir() / "sim_ax45mpv_premium"},
      {"qemu64", "VSIM_QEMU", builtin_qemu_arch(64).bin_path},
      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
  };
  std::vector<Row> rows;
  for (const A& a : arts) {
    const char* ov = std::getenv(a.env);
    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
    if (fs::is_regular_file(p))
      rows.push_back({a.label, "PASS", p.string()});
    else
      rows.push_back(
          {a.label, "FAIL", "missing " + p.string() + " -- run scripts/build_all.sh"});
  }

  const fs::path fix = root / "tests" / "fixtures";
  size_t elfs = 0;
  std::error_code ec;
  if (fs::is_directory(fix, ec))
    for (const auto& e : fs::directory_iterator(fix, ec))
      if (e.path().extension() == ".elf") ++elfs;
  if (elfs > 0)
    rows.push_back(
        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
  else
    rows.push_back({"fixtures", "FAIL",
                    "no *.elf in " + fix.string() +
                        " -- run make -C tests/fixtures"});
  return rows;
}

// --- submodules -------------------------------------------------------------

std::vector<Row> doctor_submodules() {
  const fs::path root = repo_root();
  struct M {
    const char* name;
    fs::path marker;
    const char* rel;  // marker, repo-relative (the PASS detail)
  };
  // QEMU and vsim are no longer submodules -- both are integrated as prebuilt
  // external binaries, checked in the artifacts section (qemu/vsim rows) via
  // VSIM_QEMU / VSIM_BIN_DIR. The one remaining submodule is the shared ABI.
  const M ms[] = {
      {"include/ (abi)", root / "include" / "hybrid" / "state_abi.h",
       "include/hybrid/state_abi.h"},
  };
  std::vector<Row> rows;
  for (const M& m : ms) {
    if (fs::is_regular_file(m.marker))
      rows.push_back({m.name, "PASS", m.rel});
    else
      rows.push_back({m.name, "FAIL",
                      "missing " + m.marker.string() +
                          " -- run 'git submodule update --init --recursive'"});
  }
  return rows;
}

// --- toolchain --------------------------------------------------------------

// First PATH directory holding an executable non-directory named `tool`, joined
// the way shutil.which reports it (dir + '/' + tool). "" if not found.
std::string which(const std::string& tool) {
  const char* path = std::getenv("PATH");
  if (!path) return "";
  const std::string p(path);
  for (size_t i = 0; i <= p.size();) {
    size_t j = p.find(':', i);
    if (j == std::string::npos) j = p.size();
    std::string dir = p.substr(i, j - i);
    i = j + 1;
    if (dir.empty()) continue;
    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
    std::error_code ec;
    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
      return cand;
  }
  return "";
}

// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
// to the value with surrounding whitespace, then double, then single quotes
// stripped (mirrors hsim._read_hybrid_toolchain).
bool parse_toolchain_line(const std::string& line, std::string& out) {
  size_t i = 0, n = line.size();
  auto skip_ws = [&] {
    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
  };
  skip_ws();
  const std::string kw = "export";
  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
    i += kw.size();
    skip_ws();
  }
  const std::string key = "HYBRID_TOOLCHAIN";
  if (line.compare(i, key.size(), key) != 0) return false;
  i += key.size();

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// is redirected to /dev/null; stderr too, unless relay_stderr is set, in
// which case the child inherits OUR stderr and its diagnostics stream live
// (used to surface the legs' leveled logs at --log-level <= debug). If the
// child runs longer than timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms,
                      bool relay_stderr = false);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

// Run argv with BOTH stdout and stderr captured (separate pipes) and stdin
// inherited, streaming each complete line to `on_line(stream, line)` as it
// arrives -- stream is 1 (stdout) or 2 (stderr), line excludes the trailing
// newline. The callback owns presentation (it decides what to write to the real
// streams), so this is the filtered counterpart to exec_passthrough: same "run
// to completion, no timeout, propagate exit code" contract, but the parent sees
// every line. A final unterminated line is delivered too. Returns the child's
// exit code, 128+signal if signalled, or -1 on spawn failure / empty argv.
int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int stream, std::string_view line)>& on_line);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

